#include "pick.h"
#include "store.h"

static int earlier(int a, int b) {
  return b < 0 || G[a].tag < G[b].tag ||
         (G[a].tag == G[b].tag && G[a].tid < G[b].tid) ||
         (G[a].tag == G[b].tag && G[a].tid == G[b].tid && a < b);
}

int op_pick(void) {
  PN = 0;
  for (;;) {
    int best = -1;
    for (int i = 0; i < GN; i++)
      if (!G[i].done && G[i].indeg == 0 && earlier(i, best)) best = i;

    /* No releasable node means a cycle. Break it deterministically. */
    if (best < 0)
      for (int i = 0; i < GN; i++)
        if (!G[i].done && earlier(i, best)) best = i;

    if (best < 0) break;
    PLAN[PN++] = best;
    G[best].done = 1;
    for (int k = 0; k < nsucc[best]; k++) {
      int j = succ[best][k];
      if (G[j].indeg > 0) G[j].indeg--;
    }
  }
  return PN == GN ? 0 : 2;
}
