void rk_wrap(void) {
  for (int i = 0; i < GN; i++) G[i].depth = 0;
  /* Bounded relaxation computes wait depth without an unbounded cycle queue. */
  for (int pass = 0; pass < GN; pass++) {
    int changed = 0;
    for (int i = 0; i < GN; i++) {
      for (int k = 0; k < nsucc[i]; k++) {
        int j = succ[i][k];
